// StudentLogin.js
import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { collection, getDocs } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import "./StudentLogin.css";

const StudentLogin = () => {
  const [emailOrUsername, setEmailOrUsername] = useState("");
  const [password, setPassword] = useState("");
  const [studentClass, setStudentClass] = useState("");
  const [error, setError] = useState("");
  const [students, setStudents] = useState([]);
  const navigate = useNavigate();

  // Fetch student data from Firestore
  useEffect(() => {
    const fetchStudents = async () => {
      const studentsCollectionRef = collection(db, "students");
      const data = await getDocs(studentsCollectionRef);
      setStudents(data.docs.map((doc) => ({ ...doc.data(), id: doc.id })));
    };
    fetchStudents();
  }, []);

  const handleLogin = (e) => {
    e.preventDefault();

    // Find the matching student
    const student = students.find(
      (s) =>
        (s.email === emailOrUsername || s.username === emailOrUsername) &&
        s.password === password && // Match password
        s.studentClass === studentClass // Match class
    );

    if (student) {
      setError(""); // Clear previous errors
      navigate("/studentDashboard", { state: { student } }); // Navigate to dashboard
    } else {
      setError("Invalid email/username, password, or class."); // Set error message
    }
  };

  return (
    <div className="login-container">
      <h2>Student Login</h2>
      <form onSubmit={handleLogin} className="login-form">
        <div className="form-group">
          <label htmlFor="emailOrUsername">Email or Username:</label>
          <input
            type="text"
            id="emailOrUsername"
            value={emailOrUsername}
            onChange={(e) => setEmailOrUsername(e.target.value)}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="password">Password:</label>
          <input
            type="password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </div>
        <div className="form-group">
          <label htmlFor="studentClass">Class:</label>
          <select
            id="studentClass"
            value={studentClass}
            onChange={(e) => setStudentClass(e.target.value)}
            required
          >
            <option value="" disabled>
              Select Class
            </option>
            {[
              "Primary 1",
              "Primary 2",
              "Primary 3",
              "Primary 4",
              "Primary 5",
              "Primary 6",
              "JSS 1",
              "JSS 2",
              "JSS 3",
              "SSS 1",
              "SSS 2",
              "SSS 3",
            ].map((cls) => (
              <option key={cls} value={cls}>
                {cls}
              </option>
            ))}
          </select>
        </div>
        <button type="submit" className="login-btn">
          Login
        </button>
      </form>
      {error && <p className="error-message">{error}</p>} {/* Show error */}
    </div>
  );
};

export default StudentLogin;
